var capSolver CapSolver

func init() {
	capSolver = CapSolver{
		ApiKey: "CAP-XXXXXXXXXXXXXXXXXXXX",
	}
}

func TestBalance(t *testing.T) {
	b, err := capSolver.Balance()
	if err != nil {
		log.Fatal(err)
	}
	log.Println("balance:", b.Balance)
}

func TestReCaptchaV2(t *testing.T) {
	s, err := capSolver.Solve(
		map[string]any{
			"type":       "ReCaptchaV2TaskProxyLess",
			"websiteURL": "https://www.google.com/recaptcha/api2/demo",
			"websiteKey": "6Le-wvkSAAAAAPBMRTvw0Q4Muexq9bi0DJwx_mJ-",
		})
	if err != nil {
		log.Fatal(err)
	}
	log.Println(s.Solution.GRecaptchaResponse)
}

